import{_ as a,a as n,b as s,c as t,d as o,e as i}from"./chunks/19-saaw-governed-self-morphing-v2.CtEM6EK-.js";import{_ as r,a as p}from"./chunks/03-saaw-self-morphing-loop-fixed-v2.B34zYvEG.js";import{_ as l,o as c,c as d,a2 as h}from"./chunks/framework.Cm6XCzck.js";const S=JSON.parse('{"title":"From SaaS to SaaW: When a Codebase Starts “Developing Itself”","description":"","frontmatter":{"title":"From SaaS to SaaW: When a Codebase Starts “Developing Itself”","date":"2026-08-10","column":"industry-architecture","category":"manifesto","version":"V1.1","summary":"A 23-section manifesto deriving SaaW from governance, TMPA, FCoP, Agent PC, CodeFlowMu, and Self-Morphing, anchored in Research Report Production Engine V1.3 and explicitly separating validated capabilities from research frontiers.","item_id":"MANIFESTO-20260810-SAAW","lifecycle":"Published","cover":"/assets/covers/01-saaw-manifesto-cover-agent-worker.png","visualization":"/assets/covers/02-saaw-governance-runtime-stack-fixed-v2.png","visualization_2":"/assets/covers/03-saaw-self-morphing-loop-fixed-v2.png","evidence_status":"Architecture-grounded + production-engine reference implementation","citation_status":"TMPA V1.0 DOI and publication record linked","editing_status":"Published V1.1 — full 23-section edition with TMPA V1.0 citation","publication_authorized":true,"outline":"deep"},"headers":[],"relativePath":"en/industry/2026-08-10-saaw-software-as-an-agent-worker.md","filePath":"en/industry/2026-08-10-saaw-software-as-an-agent-worker.md","lastUpdated":1786643477000}'),u={name:"en/industry/2026-08-10-saaw-software-as-an-agent-worker.md"};function g(m,e,b,f,v,y){return c(),d("div",null,[...e[0]||(e[0]=[h('<h1 id="from-saas-to-saaw-when-a-codebase-starts-developing-itself" tabindex="-1">From SaaS to SaaW: When a Codebase Starts “Developing Itself” <a class="header-anchor" href="#from-saas-to-saaw-when-a-codebase-starts-developing-itself" aria-label="Permalink to &quot;From SaaS to SaaW: When a Codebase Starts “Developing Itself”&quot;">​</a></h1><h2 id="a-manifesto-for-the-digital-employee-paradigm-grounded-in-tmpa-governance-and-codeflowmu-practice" tabindex="-1">A Manifesto for the Digital Employee Paradigm Grounded in TMPA Governance and CodeFlowMu Practice <a class="header-anchor" href="#a-manifesto-for-the-digital-employee-paradigm-grounded-in-tmpa-governance-and-codeflowmu-practice" aria-label="Permalink to &quot;A Manifesto for the Digital Employee Paradigm Grounded in TMPA Governance and CodeFlowMu Practice&quot;">​</a></h2><p><a href="/joinwell52/zh/industry/2026-08-10-saaw-software-as-an-agent-worker">中文版</a></p><p><a href="/joinwell52/assets/covers/01-saaw-manifesto-cover-agent-worker.png"><img src="'+a+`" alt="SaaW — Software as an Agent Worker"></a></p><hr><h2 id="_1-the-last-mile-that-saas-never-solved" tabindex="-1">1. The last mile that SaaS never solved <a class="header-anchor" href="#_1-the-last-mile-that-saas-never-solved" aria-label="Permalink to &quot;1. The last mile that SaaS never solved&quot;">​</a></h2><p>For the past two decades, SaaS changed how software is delivered.</p><p>Enterprises no longer buy software on discs, maintain large fleets of local servers, or pay the same deployment cost for every version upgrade. The browser became the entry point, cloud became infrastructure, and subscription became the business model.</p><p>But one thing barely changed:</p><p><strong>Humans still operate software.</strong></p><p>Employees log into ERP systems to query data and copy it into spreadsheets; open CRM systems to complete customer records; submit expenses in finance systems; approve requests in OA systems; and then move the result into yet another system.</p><p>The more software an enterprise owns, the more software its employees have to operate.</p><p>SaaS solved <strong>how software is delivered</strong>, but it did not truly solve <strong>who performs the work</strong>.</p><p>Copilot moved the boundary forward.</p><p>AI entered software interfaces to help humans draft emails, summarize documents, generate code, search knowledge, and support decisions.</p><p>But the basic relationship remained unchanged:</p><p><strong>AI gives advice; humans perform the work.</strong></p><p>Humans still sit in front of screens, clicking buttons, switching systems, entering results, and handling exceptions.</p><p>The next generation of software worth discussing should not merely be a smarter tool. It should be:</p><p><strong>software capable of performing work.</strong></p><p>We call this paradigm:</p><blockquote><p><strong>SaaW — Software as an Agent Worker</strong></p></blockquote><p>Software is no longer only a service.</p><p>Software begins to become the actor that performs work.</p><hr><h2 id="_2-from-buying-tools-to-deploying-digital-employees" tabindex="-1">2. From buying tools to deploying digital employees <a class="header-anchor" href="#_2-from-buying-tools-to-deploying-digital-employees" aria-label="Permalink to &quot;2. From buying tools to deploying digital employees&quot;">​</a></h2><p>The core change in SaaW is not simply embedding an Agent inside SaaS.</p><p>It changes the basic unit of software delivery.</p><p>SaaS delivers <strong>functionality</strong>.</p><p>Copilot delivers <strong>assistance</strong>.</p><p>SaaW delivers <strong>work</strong>.</p><p>A real SaaW should not be merely a chatbot with a system prompt.</p><p>It needs a structure closer to a real job:</p><ul><li>a clearly defined role;</li><li>clear job responsibilities;</li><li>executable workflows;</li><li>callable skills;</li><li>bounded permissions;</li><li>persistent work state;</li><li>verifiable work evidence;</li><li>a recoverable runtime environment;</li><li>explicit human authority boundaries.</li></ul><p>We therefore define SaaW as follows:</p><blockquote><p><strong>SaaW (Software as an Agent Worker) is a software paradigm in which software is delivered as a digital work actor. Under explicit job responsibilities, permission boundaries, and governance rules, it can continuously execute workflows, use business tools, produce work outcomes, and remain subject to human supervision, review, and authorization.</strong></p></blockquote><p>Enterprise software can therefore be seen as moving through a clear evolution:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SaaS</span></span>
<span class="line"><span>Software provides tools</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>Copilot</span></span>
<span class="line"><span>AI assists humans</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>Agent</span></span>
<span class="line"><span>AI executes actions</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>SaaW</span></span>
<span class="line"><span>Software performs work</span></span></code></pre></div><p>The real change is not that AI simply became smarter.</p><p><strong>The labor attribute of software changed.</strong></p><hr><h2 id="_3-the-real-enterprise-problem-trace-is-not-governance" tabindex="-1">3. The real enterprise problem: Trace is not Governance <a class="header-anchor" href="#_3-the-real-enterprise-problem-trace-is-not-governance" aria-label="Permalink to &quot;3. The real enterprise problem: Trace is not Governance&quot;">​</a></h2><p>An Agent that can call tools is not automatically ready for production.</p><blockquote><p><strong>“Traditional SaaS and multi-agent systems are, at their core, an exquisitely engineered illusion: they shackle business facts to central database state machines and filesystem topology. The moment a process crashes or a directory layout shifts, memory and permissions die with it.</strong> <strong>A real SaaW never lives on the charity of a central server. State is not encoded by changes in physical topology; facts remain forever independent of runtime instances.”</strong></p></blockquote><p>Modern multi-agent systems can generate detailed Execution Traces: who called which tool, which function ran, what result was produced, and which reasoning steps occurred.</p><p>Those traces matter.</p><p>But:</p><blockquote><p><strong>Trace ≠ Governance</strong></p></blockquote><p>Trace answers: <strong>What happened?</strong></p><p>Enterprise governance must also answer: Who authorized the work? Who accepted responsibility? Which object represents the official work fact? Who submitted the Report? Who performed the Review? Who made the Decision? Is the current state valid under the governing policy? Are references dangling? Are disagreements unresolved? After failure, who is allowed to continue?</p><p>This is not merely a logging problem.</p><p>It is a Governance State problem.</p><p>If these questions have no answers, an Agent cannot realistically assume job responsibility.</p><blockquote><p><strong>No governance, no employee.</strong></p></blockquote><p><a href="/joinwell52/assets/covers/15-saaw-trace-vs-governance-v2.svg"><img src="`+n+'" alt="Trace is not Governance: the difference between execution events and governed work state"></a></p><p><em>Supplementary view: Trace records execution events that occurred; Governance reconstructs legitimate state from durable work facts, rules, responsibility, and authority.</em></p><p>That is why TMPA exists.</p><hr><h2 id="_4-tmpa-work-facts-must-exist-independently-of-the-agent" tabindex="-1">4. TMPA: Work facts must exist independently of the Agent <a class="header-anchor" href="#_4-tmpa-work-facts-must-exist-independently-of-the-agent" aria-label="Permalink to &quot;4. TMPA: Work facts must exist independently of the Agent&quot;">​</a></h2><p>TMPA asks a simple question: when Agents and humans jointly perform long-running work, where should trustworthy work state live?</p><p>This is TMPA&#39;s formal answer:</p><blockquote><p><strong>TMPA (Textual Multi-Agent Process Architecture)</strong> is an <strong>asynchronous text-message multi-agent process architecture</strong> designed for SMEs and minimum-infrastructure conditions. Its core consists of four connected rules: <strong>text carries durable messages and state; each writer maintains its own local serial stream; multiple serial streams advance asynchronously to form parallel collaboration; the read side aggregates available evidence to reconstruct process, responsibility, lifecycle, conflicts, and audit state.</strong></p></blockquote><p><strong>This section and Sections 5–7 expand these four rules in order: this section covers durable messages and state in text; Section 5 covers local Single-Writer serial streams; Section 6 covers asynchronous parallel collaboration across streams; Section 7 covers read-side reconstruction and the Issue Set.</strong></p><p><strong>As of August 11, 2026, TMPA has entered the stable V1.0 release line:</strong> <a href="/joinwell52/en/publications/tmpa-architecture-paper-a1.0">Architecture Paper A1.0</a>, <a href="/joinwell52/en/publications/tmpa-core-specification-s1.0">Core Specification S1.0</a>, and <a href="/joinwell52/en/publications/implementation-case-i1.0">Implementation Case I1.0</a> now form the stable three-part publication set; I1.0 pins <strong>CodeFlowMu v1.8.0</strong> and records a <strong>14/14</strong> product validation result against <strong>S1.0</strong>.</p><p><a href="/joinwell52/assets/covers/16-saaw-tmpa-four-rules-v2.svg"><img src="'+s+`" alt="The four TMPA rules and reader-side fact reconstruction"></a></p><p><em>Supplementary view: Each actor appends its own facts, cross-stream references preserve partial order, and the Reader aggregates evidence without hiding conflicts.</em></p><blockquote><p><strong>“When heterogeneous Agents and humans wrestle with long-running work inside the same codebase, the most absurd choice is to entrust trustworthy state to the volatile memory of a model.</strong> <strong>TMPA has an iron law: text is fact. The physical topology of files and directories exists only to provide a compliant projection; immutable text objects are the only hard currency that survives across cycles.”</strong></p></blockquote><p>Important work facts are projected into plain, portable text.</p><p>These are not merely chat transcripts. They are formal work objects such as Task, Acceptance, Report, Review, Decision, Correction, and Issue.</p><p>Those objects form causal relationships through Reference Identifiers.</p><p>Agents can exit. Models can change. Processes can restart. Nodes can go offline.</p><p>Established work facts remain.</p><p>That is the first foundation for a long-running SaaW.</p><hr><h2 id="_5-single-writer-responsibility-needs-a-clear-source" tabindex="-1">5. Single-Writer: Responsibility needs a clear source <a class="header-anchor" href="#_5-single-writer-responsibility-needs-a-clear-source" aria-label="Permalink to &quot;5. Single-Writer: Responsibility needs a clear source&quot;">​</a></h2><p>Another core TMPA principle is:</p><blockquote><p><strong>Single-Writer Serial Streams</strong></p></blockquote><p>Each Agent or human responsibility holder is an independent Single Writer.</p><p>This means one actor does not silently rewrite facts authored by another actor.</p><p>New state is created by appending new objects.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TASK</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>ACCEPTANCE</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>REPORT</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>REVIEW</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>DECISION</span></span></code></pre></div><blockquote><p><strong>“The cancer of enterprise collaboration is the chaos of ‘anyone can change state.’</strong> <strong>In TMPA Single-Writer Serial Streams, every actor—human or Agent—is an absolutely isolated Single Writer. You may append only your own facts; you do not get to contaminate someone else’s history.</strong> <strong>Responsibility is not ‘calculated’ by database transaction locks; it ‘grows’ out of the tamper-proof reference chain of Single-Writer streams.”</strong></p></blockquote><p>This differs in an important way from many traditional workflow engines.</p><p>Traditional systems often keep mutating one central state:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>status = pending</span></span>
<span class="line"><span>status = running</span></span>
<span class="line"><span>status = review</span></span>
<span class="line"><span>status = done</span></span></code></pre></div><p>In the end, all you see is <code>status = done</code>, while the actual process that produced that state has been overwritten.</p><p>TMPA is more concerned with: Who accepted the work? Who submitted it? Who reviewed it? Who approved it? What disputes occurred? Which facts were later corrected?</p><p>State is not merely overwritten.</p><p>It is reconstructed.</p><hr><h2 id="_6-the-asynchronous-world-has-no-perfect-global-timeline" tabindex="-1">6. The asynchronous world has no perfect global timeline <a class="header-anchor" href="#_6-the-asynchronous-world-has-no-perfect-global-timeline" aria-label="Permalink to &quot;6. The asynchronous world has no perfect global timeline&quot;">​</a></h2><p>Real multi-agent systems are asynchronous.</p><p>PM may write a plan while DEV changes code, QA checks another module, OPS handles deployment, and a human supervisor approves hours later.</p><p>Forcing a perfect global sequence can hide the real concurrency.</p><p>TMPA therefore emphasizes:</p><blockquote><p><strong>Asynchronous Collaboration</strong></p></blockquote><blockquote><p><strong>“Trying to fabricate a single global timeline in an asynchronous multi-agent world is architectural arrogance.</strong> <strong>Writers do nothing but lock-free appends; the Partial-Order Graph is rebuilt dynamically on the read side. Without the blind commands of a central scheduler, multi-agent work grows wild and staggered through local text streams. That is the brutal truth of high-concurrency digital labor.”</strong></p></blockquote><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>            ┌── DEV REPORT ──┐</span></span>
<span class="line"><span>TASK ───────┤                ├── REVIEW</span></span>
<span class="line"><span>            └── OPS REPORT ──┘</span></span></code></pre></div><p>Which report happened first is less important than their causal relationship to the same Task and the Review that depends on them.</p><p>This is closer to how real organizations actually work.</p><hr><h2 id="_7-issue-set-do-not-hide-disagreement" tabindex="-1">7. Issue Set: Do not hide disagreement <a class="header-anchor" href="#_7-issue-set-do-not-hide-disagreement" aria-label="Permalink to &quot;7. Issue Set: Do not hide disagreement&quot;">​</a></h2><p>Automation systems often prefer a cosmetically green final state.</p><p>Real organizations are not like that.</p><p>References may be missing. State transitions may be illegal. QA may reject DEV. Reports may lack evidence. Decisions may lack valid preconditions. Roles may disagree.</p><p>TMPA does not try to make those problems disappear.</p><p>It makes them formal facts.</p><p>The key is not merely to list errors, but to perform <strong>read-side reconstruction</strong>. The write side does not silently resolve conflicts or treat arrival order as governance order. The Reader aggregates the currently available evidence to reconstruct process, responsibility, lifecycle, conflicts, and audit state; the <strong>Issue Set</strong> is the formal representation of conflicts, gaps, and illegal states within that reconstruction.</p><blockquote><p><strong>TMPA does not promise that conflicts never occur; it requires that conflicts cannot be hidden.</strong></p></blockquote><p>The Reader therefore reconstructs not only a Process Graph but also an Issue Set, such as:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>dangling_reference</span></span>
<span class="line"><span>illegal_transition</span></span>
<span class="line"><span>unresolved_disagreement</span></span>
<span class="line"><span>missing_acceptance</span></span>
<span class="line"><span>conflicting_review</span></span></code></pre></div><p>This is an important SaaW capability.</p><p>Enterprises do not need mythical AI that never fails.</p><p>They need AI systems that can tell where failure occurred and surface it to the right authority.</p><hr><h2 id="_8-recoverability-a-digital-employee-must-be-able-to-wake-up-and-continue" tabindex="-1">8. Recoverability: A digital employee must be able to wake up and continue <a class="header-anchor" href="#_8-recoverability-a-digital-employee-must-be-able-to-wake-up-and-continue" aria-label="Permalink to &quot;8. Recoverability: A digital employee must be able to wake up and continue&quot;">​</a></h2><p>The difference between SaaW and a chatbot is partly a difference in time scale.</p><p>A chatbot session may last minutes. Real work can last hours, days, weeks, or months.</p><p>Digital employees will encounter network interruptions, SDK timeouts, Agent exits, runtime restarts, context loss, operating-system restarts, and software upgrades.</p><p>If every failure requires telling the AI the whole story again, it cannot become a reliable Worker.</p><p>SaaW therefore needs:</p><blockquote><p><strong>Recoverability</strong></p></blockquote><p>TMPA allows governance state to be recalculated from persistent work facts.</p><p>CodeFlowMu / FCoP projects that idea into the file system.</p><p>After restart, the runtime rereads TASK, ACCEPTANCE, REPORT, REVIEW, DECISION, and ISSUE, then derives current responsibility, completed work, approved results, unresolved problems, legal next actions, and the next actor.</p><p>Recovery is not about restoring an Agent&#39;s memory.</p><p>It is about reconstructing the facts of work.</p><hr><h3 id="a-day-in-the-life-of-a-digital-researcher-research-report-production-engine-v1-3" tabindex="-1">A Day in the Life of a Digital Researcher: Research Report Production Engine V1.3 <a class="header-anchor" href="#a-day-in-the-life-of-a-digital-researcher-research-report-production-engine-v1-3" aria-label="Permalink to &quot;A Day in the Life of a Digital Researcher: Research Report Production Engine V1.3&quot;">​</a></h3><p>There is no need to invent a fictional job. The <strong>Research Report Production Engine V1.3</strong> already gives us a real, observable example of a digital researcher at work.</p><p><strong>09:00 · Research Discovery</strong><br> The digital researcher starts the day by scanning new research signals, engineering changes, and open questions, deciding what deserves attention.<br><strong>Output: Signal Pool.</strong></p><p><strong>10:00 · Research Queue</strong><br> It selects the research object that should actually move forward that day, sets priority, and decides what the day&#39;s research will focus on. It does not turn every signal into an article.<br><strong>Output: Today&#39;s Research Plan.</strong></p><p><strong>11:00 · Research Reading</strong><br> It reads papers, specifications, engineering records, code, test results, and existing material around the selected object, organizes usable evidence, and records what is still missing.<br><strong>Output: Reading Result.</strong></p><p><strong>13:00 · Research Analysis</strong><br> It turns the morning&#39;s material into judgments: which facts hold, which statements remain inference, where disagreement exists, what the boundary conditions are, and what research conclusion should be formed next.<br><strong>Output: Research Object.</strong></p><p><strong>15:00 · Research Production</strong><br> The digital researcher turns the research object into a formal work product: structuring the article, drafting the report, checking evidence, and adding required diagrams or visualizations until a publishable candidate exists.<br><strong>Output: Publication Candidate.</strong></p><p><strong>20:00 · Formal Publication</strong><br> Once the candidate satisfies publication conditions, it enters the formal release path: committing to GitHub, generating the website, verifying the commit, and confirming the release. If an action requires accountable human authority, the work stops at that authority boundary and waits for a human decision.</p><p><strong>Output: Formally Published Research Result.</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>09:00 Research Discovery   → Signal Pool</span></span>
<span class="line"><span>10:00 Research Queue       → Today&#39;s Research Plan</span></span>
<span class="line"><span>11:00 Research Reading     → Reading Result</span></span>
<span class="line"><span>13:00 Research Analysis    → Research Object</span></span>
<span class="line"><span>15:00 Research Production  → Publication Candidate</span></span>
<span class="line"><span>20:00 Formal Publication   → GitHub + Website + Commit Verify + Release</span></span></code></pre></div><p>That is a day in the life of a digital researcher: <strong>it is not answering one question; it is continuously performing a research job under a defined role and work rhythm.</strong></p><hr><h2 id="_9-fcop-file-based-coordination-protocol" tabindex="-1">9. FCoP: File-based Coordination Protocol <a class="header-anchor" href="#_9-fcop-file-based-coordination-protocol" aria-label="Permalink to &quot;9. FCoP: File-based Coordination Protocol&quot;">​</a></h2><p><strong>FCoP (File-based Coordination Protocol) is a multi-agent behavioral-governance protocol that uses the filesystem as its only synchronization primitive.</strong></p><p>Its core invariant is <strong>Filename as Protocol</strong>. In its project-visible filesystem profile:</p><ul><li><strong>directory is state</strong>: <code>_lifecycle/{inbox,active,review,done,archive}/</code>;</li><li><strong>filename is routing</strong>: sender, recipient, type, and sequence identify origin, destination, and work-object identity;</li><li><strong>content is payload</strong>: Markdown plus YAML frontmatter carries tasks, reports, issues, references, and governance facts;</li><li><strong><code>os.rename()</code> is the only synchronization operation</strong>: lifecycle transitions rely on atomic filesystem moves rather than a coordination database, message broker, or central lock service.</li></ul><p>A task lifecycle is therefore directly observable:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>inbox      waiting to be claimed</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>active     in execution</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>review     awaiting review</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>done       completed</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>archive    archived</span></span></code></pre></div><p><a href="/joinwell52/assets/covers/17-saaw-fcop-lifecycle-v2.svg"><img src="`+t+`" alt="The FCoP project-visible lifecycle and shared fact plane"></a></p><p><em>Supplementary view: Lifecycle changes are expressed through project-visible work objects; humans, Agents, Readers, and operations tools observe the same fact plane.</em></p><p>FCoP governs <strong>Agent collaboration behavior</strong>: how tasks are handed off, results are reported, issues are raised, capability boundaries are declared, and those behaviors leave event semantics, failure boundaries, and auditable evidence.</p><p><strong>FCoP does not govern the execution runtime.</strong> Scheduling, process management, model sessions, resource allocation, identity authentication, and runtime-node management are outside the protocol itself.</p><p>In the TMPA implementation relationship, FCoP acts as a <strong>project-visible filesystem profile</strong>. It does not require a coordination database, message broker, or enterprise control plane; conversely, it does not by itself provide validated enterprise identity, strong role isolation, tamper-resistant storage, or Byzantine fault tolerance. This is consistent with TMPA being <strong>SME-first, not SME-only</strong>: larger deployments can add databases, object stores, event services, identity systems, and control planes without changing the governance semantics carried by the protocol.</p><p>Most importantly, <strong>the FCoP protocol, packages, host-adapter responsibilities, reference implementation, and runtime environment are not the same thing.</strong> With TMPA V1.0 formally released, this operating relationship is now frozen in the stable <strong>A1.0 / S1.0 / I1.0</strong> release line. The operational stack can be represented directly as:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Application / Runtime</span></span>
<span class="line"><span>CodeFlowMu / Cursor / Claude Desktop</span></span>
<span class="line"><span>                │</span></span>
<span class="line"><span>                ▼</span></span>
<span class="line"><span>Host Adapter Layer</span></span>
<span class="line"><span>fcop-mcp / host bridges</span></span>
<span class="line"><span>                │</span></span>
<span class="line"><span>                ▼</span></span>
<span class="line"><span>★ FCoP Protocol Layer ★</span></span>
<span class="line"><span>behavior governance / handoff / reporting / review</span></span>
<span class="line"><span>capability boundaries / event semantics / failure boundaries / audit</span></span>
<span class="line"><span>                │</span></span>
<span class="line"><span>                ▼</span></span>
<span class="line"><span>Reference Implementation</span></span>
<span class="line"><span>fcop Python library</span></span>
<span class="line"><span>                │</span></span>
<span class="line"><span>                ▼</span></span>
<span class="line"><span>Execution Substrate</span></span>
<span class="line"><span>LLM APIs / MCP tools / filesystem / process manager / operating system</span></span></code></pre></div><p>Therefore:</p><ul><li><code>fcop</code> is a Python package distributed on PyPI and the <strong>reference implementation of FCoP</strong>; it also provides the CLI capability;</li><li><code>fcop-mcp</code> is an FCoP MCP tool package distributed on PyPI; in the operational stack it performs <strong>host-adapter responsibilities</strong>, exposing FCoP capabilities to actual hosts;</li><li><strong>CodeFlowMu is an application/runtime system that uses FCoP as its coordination protocol.</strong></li><li>TMPA is not a runtime layer in this stack; it supplies the higher-level governance semantics and architectural guidance the stack is intended to realize.</li></ul><p>This also explains why “directory is state” matters: administrators, human supervisors, Agents, and debugging tools can inspect the same project-visible facts without first entering a hidden central coordination state.</p><hr><h2 id="_10-codeflowmu-from-protocol-to-the-real-runtime-world" tabindex="-1">10. CodeFlowMu: From protocol to the real runtime world <a class="header-anchor" href="#_10-codeflowmu-from-protocol-to-the-real-runtime-world" aria-label="Permalink to &quot;10. CodeFlowMu: From protocol to the real runtime world&quot;">​</a></h2><p>If TMPA defines work-fact and governance semantics, and FCoP supplies a project-visible file-based coordination protocol, then <strong>CodeFlowMu addresses how those semantics and that protocol enter a real Agent runtime world.</strong></p><p>CodeFlowMu did not begin by constructing a giant central Agent Runtime.</p><p>Instead, it remains deliberately restrained: reasoning is delegated to mature model ecosystems, tools remain in real operating environments, and CodeFlowMu concentrates on work orchestration, Agent responsibility boundaries, lifecycle, FCoP integration, Skill invocation, Reports, Reviews, human decisions, recovery, and runtime governance.</p><p>This creates an important engineering boundary:</p><p><strong>CodeFlowMu does not need to reinvent the LLM, and it does not redefine FCoP.</strong></p><p>The model is only one part of a digital employee&#39;s brain; FCoP is the coordination protocol it uses; what determines whether the digital employee can sustain responsibility is the surrounding work structure, runtime environment, and governance loop.</p><p><a href="/joinwell52/assets/covers/02-saaw-governance-runtime-stack-fixed-v2.png"><img src="`+r+'" alt="SaaW governance and runtime architecture: SaaW, CodeFlowMu, FCoP, and TMPA"></a></p><p><em>Figure 1. TMPA supplies work-fact and governance architecture; FCoP supplies the file-based coordination protocol; CodeFlowMu provides the engineering runtime; SaaW names the resulting software-delivery paradigm.</em></p><p><a href="/joinwell52/assets/covers/18-saaw-codeflowmu-runtime-boundary-v2.svg"><img src="'+o+`" alt="The CodeFlowMu engineering runtime boundary"></a></p><p><em>Supplementary view: Models reason and tools act. CodeFlowMu organizes work, FCoP carries facts, and TMPA guides governance semantics.</em></p><hr><h2 id="_11-agent-pc-a-real-digital-employee-needs-a-computer" tabindex="-1">11. Agent PC: A real digital employee needs a “computer” <a class="header-anchor" href="#_11-agent-pc-a-real-digital-employee-needs-a-computer" aria-label="Permalink to &quot;11. Agent PC: A real digital employee needs a “computer”&quot;">​</a></h2><p>If SaaW is a Worker, the Worker needs a work environment.</p><p>We call this runtime node:</p><blockquote><p><strong>Agent PC</strong></p></blockquote><p>It does not have to be a physical computer. It represents an independent runtime environment containing Reasoning, Skills, Workflow, Credentials, Runtime, Files, Governance, and External Systems.</p><p>It may use browsers, APIs, CLI tools, scripts, MCP, internal enterprise services, and controlled automation hooks.</p><p>The loop therefore changes from <code>Prompt → Response</code> into:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Task</span></span>
<span class="line"><span> ↓</span></span>
<span class="line"><span>Reason</span></span>
<span class="line"><span> ↓</span></span>
<span class="line"><span>Use Skill</span></span>
<span class="line"><span> ↓</span></span>
<span class="line"><span>Operate Business System</span></span>
<span class="line"><span> ↓</span></span>
<span class="line"><span>Observe Result</span></span>
<span class="line"><span> ↓</span></span>
<span class="line"><span>Produce Evidence</span></span>
<span class="line"><span> ↓</span></span>
<span class="line"><span>Continue / Report / Escalate</span></span></code></pre></div><p>That is a digital-worker runtime loop.</p><hr><h2 id="_12-non-invasive-digital-employees-let-ai-use-software-not-bypass-software" tabindex="-1">12. Non-invasive digital employees: Let AI use software, not bypass software <a class="header-anchor" href="#_12-non-invasive-digital-employees-let-ai-use-software-not-bypass-software" aria-label="Permalink to &quot;12. Non-invasive digital employees: Let AI use software, not bypass software&quot;">​</a></h2><p>One of the most dangerous temptations in enterprise automation is to let AI modify the database directly.</p><p>That may look extremely efficient.</p><p>But real enterprise systems are not simple CRUD layers.</p><p>A single field may sit behind state machines, triggers, stored procedures, permission rules, financial constraints, workflows, audit trails, and external-system integrations.</p><p>Writing directly to tables can bypass decades of accumulated business boundaries.</p><p>SaaW should therefore prefer a different path:</p><p><strong>AI operates the business system rather than bypassing the business system.</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Agent</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ├── API</span></span>
<span class="line"><span>  ├── Browser</span></span>
<span class="line"><span>  ├── CLI</span></span>
<span class="line"><span>  ├── Controlled Hook</span></span>
<span class="line"><span>  └── Approved Automation</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>Existing ERP / CRM / Business System</span></span></code></pre></div><p>The point is not to guarantee that AI will never make mistakes. It is to keep mistakes, as far as possible, inside boundaries where existing business rules can observe, reject, audit, and roll them back.</p><p>That is the engineering posture enterprise AI automation actually requires.</p><hr><h2 id="_13-rediscovering-enterprise-sop-from-code" tabindex="-1">13. Rediscovering enterprise SOP from code <a class="header-anchor" href="#_13-rediscovering-enterprise-sop-from-code" aria-label="Permalink to &quot;13. Rediscovering enterprise SOP from code&quot;">​</a></h2><p>Legacy software contains an often underestimated asset:</p><p><strong>Code itself is enterprise knowledge.</strong></p><p>Many enterprise processes do not have complete SOP documentation.</p><p>The real rules are often hidden in APIs, controllers, forms, validation logic, state transitions, permission checks, batch scripts, database schemas, and configuration.</p><p>An important direction for CodeFlowMu is therefore to let a Meta-Development Team analyze existing systems and help reconstruct:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Existing Code</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span>      ▼</span></span>
<span class="line"><span>Business Rules</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span>      ▼</span></span>
<span class="line"><span>Workflow</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span>      ▼</span></span>
<span class="line"><span>SOP</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span>      ▼</span></span>
<span class="line"><span>Digital Employee Skills</span></span></code></pre></div><p>But this does not mean that “scanning code = automatically understanding the entire enterprise.”</p><p>Real SOP may also come from documents, human explanations, API specifications, operation recordings, job descriptions, policy rules, and domain-expert feedback.</p><p>Code is only one extremely important source of facts among them.</p><p>A more rigorous formulation is:</p><blockquote><p><strong>Enterprise Evidence → Candidate SOP → Validation → Governed Workflow</strong></p></blockquote><p>AI makes it possible to restructure these scattered forms of knowledge at much lower cost; but a Candidate SOP should become an executable digital-employee workflow only after business validation, engineering testing, governance checks, or human authorization.</p><hr><h2 id="_14-codeflowmu-s-second-form-meta-development-runtime" tabindex="-1">14. CodeFlowMu&#39;s second form: Meta-Development Runtime <a class="header-anchor" href="#_14-codeflowmu-s-second-form-meta-development-runtime" aria-label="Permalink to &quot;14. CodeFlowMu&#39;s second form: Meta-Development Runtime&quot;">​</a></h2><p>The most important thing about CodeFlowMu is not merely that multiple Agents can develop software together.</p><p>More importantly, that development capability can itself become production capability for the next generation of digital employees.</p><p>We call this form the <strong>Meta-Development Runtime</strong>.</p><p>An initial CodeFlowMu instance can appear as a four-role development team:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌───────────────────────────────┐</span></span>
<span class="line"><span>│      CodeFlowMu Meta Team     │</span></span>
<span class="line"><span>│                               │</span></span>
<span class="line"><span>│ PM        DEV       QA    OPS │</span></span>
<span class="line"><span>└───────────────────────────────┘</span></span></code></pre></div><p>Each role has its own responsibility boundary.</p><p>PM interprets requirements, decomposes work, and organizes collaboration.</p><p>DEV implements code, Skills, Hooks, and workflows.</p><p>QA verifies business outcomes and engineering outcomes.</p><p>OPS manages the runtime environment, recovery, deployment, and lifecycle.</p><p>This is CodeFlowMu&#39;s <strong>Meta-Development Mode</strong>.</p><p>Its output does not have to be only traditional software. It can also be:</p><p><strong>a Digital Employee Package.</strong></p><hr><h2 id="_15-digital-employee-package-turning-digital-employees-into-engineered-products" tabindex="-1">15. Digital Employee Package: Turning Digital Employees into Engineered Products <a class="header-anchor" href="#_15-digital-employee-package-turning-digital-employees-into-engineered-products" aria-label="Permalink to &quot;15. Digital Employee Package: Turning Digital Employees into Engineered Products&quot;">​</a></h2><p>Before a digital employee can truly be deployed, it needs an engineering description.</p><p>A complete Digital Employee Package typically includes at least:</p><ul><li>role;</li><li>job responsibilities;</li><li>workflow;</li><li>Skills;</li><li>permissions;</li><li>governance policies;</li><li>validation rules;</li><li>runtime configuration;</li><li>recovery rules;</li><li>human decision gates.</li></ul><p>For the first time, a digital employee begins to look like a real software product: it can be defined, developed, tested, versioned, deployed, upgraded, and rolled back.</p><p>That is one of the fundamental differences between SaaW and “writing an Agent prompt.”</p><hr><h3 id="a-real-engineering-anchor-the-saaw-manifesto-is-part-of-the-case" tabindex="-1">A Real Engineering Anchor: The SaaW Manifesto Is Part of the Case <a class="header-anchor" href="#a-real-engineering-anchor-the-saaw-manifesto-is-part-of-the-case" aria-label="Permalink to &quot;A Real Engineering Anchor: The SaaW Manifesto Is Part of the Case&quot;">​</a></h3><p>There is an important recursive relationship here.</p><p>We are not first writing a manifesto that claims SaaW exists and then searching for a fictional example to prove it. <strong>We use the operating Research Report Production Engine V1.3 to explain SaaW, while this SaaW Manifesto itself becomes a research artifact managed, reviewed, and published through that production system.</strong></p><p>The research-production chain can be written as:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Research Question</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Research Object</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Evidence / Reading</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Analysis</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Report</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Evidence Gate</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Visualization</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Human Authorization</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Publication</span></span></code></pre></div><p>Expressed in SaaW worker terms, the same chain becomes:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Role → Workflow → Skills → Work State → Evidence</span></span>
<span class="line"><span>     → Governance → Human Authority → Work Outcome</span></span></code></pre></div><p>These are not two different systems. They are two descriptions of the same fact: software begins to take on continuous work under explicit responsibilities, evidence rules, and authority boundaries.</p><blockquote><p><strong>This is not an AI writing tool. It is a governed research worker.</strong></p></blockquote><hr><h2 id="_16-self-morphing-when-the-codebase-begins-to-develop-itself" tabindex="-1">16. Self-Morphing: When the codebase begins to “develop itself” <a class="header-anchor" href="#_16-self-morphing-when-the-codebase-begins-to-develop-itself" aria-label="Permalink to &quot;16. Self-Morphing: When the codebase begins to “develop itself”&quot;">​</a></h2><p>Now we reach the central idea of this manifesto:</p><blockquote><p><strong>Self-Morphing</strong></p></blockquote><p>It does not mean that an Agent freely mutates its source code, and it does not mean unrestricted AI self-replication.</p><blockquote><p><strong>Self-Morphing means that a digital-employee runtime can use its own software-development capability to construct, validate, and deploy new digital-worker forms.</strong></p></blockquote><p><a href="/joinwell52/assets/covers/03-saaw-self-morphing-loop-fixed-v2.png"><img src="`+p+'" alt="Self-Morphing: from meta-development runtime to the digital-worker work loop"></a></p><p><em>Figure 2. The governed Self-Morphing loop brings development, validation, authorization, deployment, work execution, and work evidence into one recoverable and traceable lifecycle.</em></p><p><a href="/joinwell52/assets/covers/19-saaw-governed-self-morphing-v2.svg"><img src="'+i+`" alt="The governed Meta-Development and Self-Morphing loop"></a></p><p><em>Supplementary view: Production evidence can enter meta-development, but meta-development cannot rewrite the live production runtime; validation and authorization control deployment, with rollback preserved.</em></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Meta-Dev Runtime</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>Analyze Existing Work</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>Develop Worker Package</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>Validate</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>Human / Governance Decision</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>Deploy</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>Domain Worker Runtime</span></span></code></pre></div><p>For example:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PM / DEV / QA / OPS</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        │ develops</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>Finance Worker Package</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>Invoice Agent</span></span>
<span class="line"><span>ERP Entry Agent</span></span>
<span class="line"><span>Compliance Agent</span></span>
<span class="line"><span>Archive Agent</span></span></code></pre></div><p>Or:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PM / DEV / QA / OPS</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>Contract Worker Package</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>Risk Analysis Agent</span></span>
<span class="line"><span>Signing Agent</span></span>
<span class="line"><span>Compliance Agent</span></span>
<span class="line"><span>Archive Agent</span></span></code></pre></div><p>Traditional software development looks like:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Human</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>builds Software</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>Human uses Software</span></span></code></pre></div><p>Self-Morphing introduces another pattern:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AI Development Team</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>builds Digital Worker</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Digital Worker performs Work</span></span></code></pre></div><p>And the next step is even more important:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Worker performs Work</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>Evidence / Issues</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>Development Input</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>Next Worker Version</span></span></code></pre></div><p>Development and work begin to form one loop:</p><blockquote><p><strong>Develop → Validate → Deploy → Work → Observe → Improve</strong></p></blockquote><p>That is the meaningful engineering interpretation of “the codebase develops itself.”</p><hr><h2 id="_17-from-development-runtime-to-work-runtime" tabindex="-1">17. From Development Runtime to Work Runtime <a class="header-anchor" href="#_17-from-development-runtime-to-work-runtime" aria-label="Permalink to &quot;17. From Development Runtime to Work Runtime&quot;">​</a></h2><p>Traditional software separates development, production runtime, and human work.</p><p>SaaW begins to recombine them.</p><p>CodeFlowMu&#39;s long-term direction can be expressed as follows:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Development Runtime</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>Digital Employee Package</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>Work Runtime</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>Work Evidence</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>Development Runtime</span></span></code></pre></div><p>This is not merely DevOps.</p><p>DevOps connects Development and Deployment.</p><p>SaaW attempts to connect:</p><p><strong>Development and Work.</strong></p><p>That may become one of the deepest boundaries between AI-native and traditional software.</p><hr><h2 id="_18-humans-do-not-disappear-they-leave-the-operation-layer" tabindex="-1">18. Humans do not disappear; they leave the operation layer <a class="header-anchor" href="#_18-humans-do-not-disappear-they-leave-the-operation-layer" aria-label="Permalink to &quot;18. Humans do not disappear; they leave the operation layer&quot;">​</a></h2><p>The appearance of digital employees does not mean removing humans from the work loop.</p><p>On the contrary.</p><p>A safe SaaW must clearly define which actions an Agent can complete autonomously within its authority, and which actions must be decided by a human.</p><p><strong>In SaaS, humans usually remain in the software operation layer; in SaaW, humans increasingly move into supervision and final authorization.</strong></p><p>Low-risk work such as querying, organizing, validation, report generation, and internal synchronization can become highly automated.</p><p>Large payments, final contract signatures, permission escalation, irreversible data operations, and important public publication should enter explicit human decision gates.</p><p>More precisely:</p><blockquote><p><strong>Human at the Authority Boundary.</strong></p></blockquote><hr><h2 id="_19-pwa-the-mobile-control-plane-for-a-digital-employee-team" tabindex="-1">19. PWA: The mobile control plane for a digital-employee team <a class="header-anchor" href="#_19-pwa-the-mobile-control-plane-for-a-digital-employee-team" aria-label="Permalink to &quot;19. PWA: The mobile control plane for a digital-employee team&quot;">​</a></h2><p>The CodeFlowMu PWA is therefore not merely a mobile webpage.</p><p>It represents the digital-employee team&#39;s <strong>Human Control Plane</strong>.</p><p>A manager can use a mobile device to inspect current tasks, Agent state, Reports, Reviews, Issues, pending decisions, recovery state, and work outcomes.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SaaW Runtime</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span>      ▼</span></span>
<span class="line"><span>Report</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span>      ▼</span></span>
<span class="line"><span>FCoP / TMPA Work Facts</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span>      ▼</span></span>
<span class="line"><span>Reader</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span>      ▼</span></span>
<span class="line"><span>Mobile PWA</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span>      ▼</span></span>
<span class="line"><span>Human Approves / Rejects</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span>      ▼</span></span>
<span class="line"><span>Formal Decision</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span>      ▼</span></span>
<span class="line"><span>SaaW Runtime continues</span></span></code></pre></div><p>The most important point is that approval is not merely a UI click.</p><p>The click is only the interface.</p><p>What actually happens is:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Human Decision</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Governance Fact</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>State Transition</span></span></code></pre></div><p>Authorization therefore becomes part of the formal work history.</p><p>That is <strong>Human-in-the-Loop Governance</strong> in the real sense.</p><hr><h2 id="_20-a-digital-employee-must-not-depend-on-a-model-session-that-never-disconnects" tabindex="-1">20. A digital employee must not depend on a model session that never disconnects <a class="header-anchor" href="#_20-a-digital-employee-must-not-depend-on-a-model-session-that-never-disconnects" aria-label="Permalink to &quot;20. A digital employee must not depend on a model session that never disconnects&quot;">​</a></h2><p>Many Agent products today hide a dangerous assumption: that the model session will always remain alive.</p><p>The real world does not work that way.</p><p>Models time out. Context windows overflow. Gateways fail. Agents crash. Software upgrades. Servers restart.</p><p>A real SaaW must therefore follow one critical principle:</p><blockquote><p><strong>Agents are replaceable. Work facts are not.</strong></p></blockquote><p>Agents can change. Models can change. SDKs can change. Runtimes can restart.</p><p>But already established work facts must not disappear with them.</p><p>This is where TMPA, FCoP, and CodeFlowMu ultimately converge:</p><p><strong>Decouple intelligence from session continuity, and build work continuity on durable facts.</strong></p><p>This may be one of the most important architectural principles for building long-running digital employees.</p><hr><h2 id="_21-saaw-changes-software-economics-not-merely-ai" tabindex="-1">21. SaaW changes software economics, not merely AI <a class="header-anchor" href="#_21-saaw-changes-software-economics-not-merely-ai" aria-label="Permalink to &quot;21. SaaW changes software economics, not merely AI&quot;">​</a></h2><p>Ultimately, SaaW is not merely another Agent Framework.</p><p>It may imply a change in the economic model of software.</p><p>The SaaS business logic is: enterprises buy software capability and then continue staffing people to perform the work.</p><p>The SaaW business logic may become: enterprises deploy digital work capacity, and work outcomes become part of software delivery for the first time.</p><p>Therefore:</p><p><strong>SaaS sells capability.</strong><br><strong>SaaW delivers work.</strong></p><p>Enterprises may eventually buy not only CRM, but a digital customer-operations team; not only finance software, but digital finance workers; not only a contract-management platform, but a digital contract-review and fulfillment team.</p><p>The software market may gradually expand from a <strong>software market</strong> into a:</p><blockquote><p><strong>Digital Labor Market</strong></p></blockquote><p>That is the much larger space of possibility opened by SaaW.</p><hr><h2 id="_22-saaw-is-not-a-new-chat-box" tabindex="-1">22. SaaW is not a new chat box <a class="header-anchor" href="#_22-saaw-is-not-a-new-chat-box" aria-label="Permalink to &quot;22. SaaW is not a new chat box&quot;">​</a></h2><p>The whole argument can be reduced to one sentence:</p><p><strong>A digital employee is not a smarter chatbot.</strong></p><p>It requires job responsibilities, a work environment, tools, permissions, state, governance, evidence, recovery capability, and human authority boundaries.</p><p>TMPA studies how those work facts become valid.</p><p>FCoP studies how coordination can be projected in an extremely lightweight way.</p><p>CodeFlowMu studies how Agents actually form teams and continue working.</p><p>Agent PC provides the work environment.</p><p>PWA provides the human control surface.</p><p>SaaW gives the whole transition a higher-level name:</p><blockquote><p><strong>Software as an Agent Worker</strong></p></blockquote><hr><h2 id="_23-from-saas-to-saaw" tabindex="-1">23. From SaaS to SaaW <a class="header-anchor" href="#_23-from-saas-to-saaw" aria-label="Permalink to &quot;23. From SaaS to SaaW&quot;">​</a></h2><p>For the past forty years, software has largely answered one question:</p><blockquote><p><strong>How can we help humans work more efficiently?</strong></p></blockquote><p>AI-native software is beginning to face another:</p><blockquote><p><strong>Which work can software itself perform?</strong></p></blockquote><p>This does not mean software will replace everyone.</p><p>The deeper change may be that humans gradually leave repetitive software operation, Agents enter the operation layer, and humans move into the governance layer.</p><p>So:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SaaS</span></span>
<span class="line"><span>Human operates Software</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Copilot</span></span>
<span class="line"><span>Human operates with AI</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>SaaW</span></span>
<span class="line"><span>AI performs Work</span></span>
<span class="line"><span>Human governs and authorizes AI</span></span></code></pre></div><p>And when a system capable of developing digital workers begins to use that capability to develop the next generation of digital workers:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AI develops Digital Worker</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Digital Worker performs Work</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Work produces Evidence</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Evidence drives the next Development cycle</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>AI develops the next Digital Worker</span></span></code></pre></div><p>A software lifecycle that did not previously exist begins to form.</p><h3 id="validated-today" tabindex="-1">Validated (Today) <a class="header-anchor" href="#validated-today" aria-label="Permalink to &quot;Validated (Today)&quot;">​</a></h3><p>To avoid packaging research directions as already completed product capability, the engineering facts that exist today should be stated separately:</p><ul><li>FCoP&#39;s file-driven lifecycle, task handoff, Reports, and Issues;</li><li>real PM / DEV / QA / OPS four-role Agent collaboration loops;</li><li><code>Report</code>, <code>Review</code>, <code>Decision</code>, and human approval paths;</li><li>the PWA human control plane and pending-decision handling;</li><li>recovery governance after runtime interruption;</li><li>TMPA Reader, specification tests, and reconstruction of work facts;</li><li>real CodeFlowMu engineering cases;</li><li>the Research Report Production Engine V1.3 production chain from research task to governed publication.</li></ul><h3 id="under-exploration-next" tabindex="-1">Under Exploration (Next) <a class="header-anchor" href="#under-exploration-next" aria-label="Permalink to &quot;Under Exploration (Next)&quot;">​</a></h3><p>Still under research, standardization, or broader engineering validation are:</p><ul><li>standardized Digital Employee Packages;</li><li>standardized Agent PC;</li><li>role-specific Work Runtimes;</li><li>Candidate SOP extraction from legacy systems and enterprise evidence;</li><li>Meta-Development Runtime → Domain Worker Runtime transformation;</li><li>governed Self-Morphing.</li></ul><p>This distinction is not conservatism; it is part of credibility: <strong>validated capability should be stated with evidence, while frontier capability should remain a research proposition.</strong> Self-Morphing is more credible precisely because it is built on governance, recovery, work facts, and engineering runtime capabilities that already exist.</p><p>That is the direction CodeFlowMu is exploring.</p><p>Not another Multi-Agent Framework.</p><p>Instead:</p><blockquote><p><strong>Software infrastructure capable of developing, running, governing, recovering, and continuously evolving digital employees.</strong></p></blockquote><p>That is the real reason we propose SaaW.</p><blockquote><p><strong>SaaW — Software as an Agent Worker</strong></p></blockquote><p>Software was once a tool.</p><p>Then it became a service.</p><p>Now, it is beginning to work.</p><p><strong>From Software Market to Digital Labor Market.</strong></p><hr><blockquote><p><strong>Author / Publisher:</strong> joinwell52 Research Center / CodeFlowMu Core Team</p><p><strong>Architecture and Theory:</strong> TMPA Architecture Paper — <strong>A1.0</strong></p><p><strong>Normative Standard:</strong> TMPA Core Specification — <strong>S1.0</strong></p><p><strong>Implementation Case (author-run engineering evidence):</strong> TMPA–FCoP–CodeFlowMu Implementation Case — <strong>I1.0 (CodeFlowMu v1.8.0 · S1.0 C01–C14 14/14 PASS)</strong></p><p><strong>Formal Publication:</strong> TMPA V1.0 Publication System, 2026-08-11</p><p><strong>DOI:</strong> <a href="https://doi.org/10.5281/zenodo.21888488" target="_blank" rel="noreferrer">10.5281/zenodo.21888488</a></p><p><strong>Release Record:</strong> <a href="/joinwell52/en/publications/tmpa-v1.0-release-record">TMPA V1.0 Formal Release Record</a></p><p><strong>Core Engineering Vehicle:</strong> CodeFlowMu / FCoP</p></blockquote><blockquote><p><strong>V1.1 scope note:</strong> This is a technical manifesto for AI-native software, multi-agent engineering, and enterprise digital employees. SaaW, Self-Morphing, and Digital Employee Runtime combine current architecture and engineering practice with active research directions. Capability boundaries are defined by the corresponding public specifications, tests, and implementation evidence.</p></blockquote>`,362)])])}const P=l(u,[["render",g]]);export{S as __pageData,P as default};
